from typing import TYPE_CHECKING

from .manager import add_magic_file, remove_magic_file

if TYPE_CHECKING:
    from .qbraid_magic import SysMagics

__all__ = [  # pylint: disable=undefined-all-variable
    "SysMagics",
    "add_magic_file",
    "remove_magic_file",
]


def __getattr__(name):
    if name == "SysMagics":
        from .qbraid_magic import SysMagics  # pylint: disable=import-outside-toplevel

        return SysMagics
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
